import{_ as d,o as l,c as r,a2 as i}from"./chunks/framework.aJDz64y9.js";const p=JSON.parse('{"title":"Налёты на магазины","description":"","frontmatter":{},"headers":[],"relativePath":"crime/stores.md","filePath":"crime/stores.md","lastUpdated":1794540927000}'),a={name:"crime/stores.md"};function e(o,t,s,n,h,c){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="налеты-на-магазины" tabindex="-1">Налёты на магазины <a class="header-anchor" href="#налеты-на-магазины" aria-label="Permalink to &quot;Налёты на магазины&quot;">​</a></h1><p>Магазин грабят тремя способами — стащить днём, вскрыть ночью или взять налётом. Во всех трёх добычу хватают руками с полок, а касса даёт меньшую часть суммы.</p><h2 id="типы-магазинов" tabindex="-1">Типы магазинов <a class="header-anchor" href="#типы-магазинов" aria-label="Permalink to &quot;Типы магазинов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Тип</th><th>Что на полках</th><th>Чем опасен</th><th>Кому идёт добыча</th></tr></thead><tbody><tr><td>Продуктовый, алкомаркет</td><td>Алкоголь, сигареты, мелкая наличность</td><td>Продавец с тревожной кнопкой</td><td>NPC-скупщик, бары игроков</td></tr><tr><td>Одежда</td><td>Брендовые вещи с магнитными метками</td><td>Рамки на выходе, много свидетелей</td><td>Барахолка, скупщик-игрок</td></tr><tr><td>Электроника</td><td>Телефоны, ноутбуки, приставки, телевизоры</td><td>Запертые витрины, серийники, метки в коробках</td><td>Скупщик-игрок, мастера — на детали</td></tr><tr><td>Оружейный</td><td>Детали, обвесы и патроны, не готовые стволы</td><td>Вооружённый продавец, решётки, быстрый выезд полиции</td><td>Оружейники-игроки</td></tr><tr><td>Ювелирный</td><td>Украшения в витринах</td><td>Датчики на стекле, охрана</td><td>Скупщик-игрок, заказы</td></tr></tbody></table><p>Готовое оружие с полок не берётся: иначе оружейный станет бесплатным арсеналом и обрушит цены на стволы.</p><h2 id="три-способа" tabindex="-1">Три способа <a class="header-anchor" href="#три-способа" aria-label="Permalink to &quot;Три способа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Способ</th><th>Когда</th><th>Команда</th><th>Суть</th><th>Тяжесть статьи</th></tr></thead><tbody><tr><td>Магазинная кража</td><td>Днём, магазин открыт</td><td>1</td><td>Спрятать товар, пока продавец и камера смотрят в другую сторону</td><td>Лёгкая</td></tr><tr><td>Ночной взлом</td><td>Магазин закрыт</td><td>2–3</td><td>Обесточить щиток, вскрыть заднюю дверь, вынести полки</td><td>Средняя</td></tr><tr><td>Налёт</td><td>Магазин открыт</td><td>3–4</td><td>Маски, продавец под прицелом, полки и касса на время</td><td>Тяжёлая</td></tr></tbody></table><p>Магазинная кража — входная ступень для новичка без инструмента и команды. У продавца и камеры есть сектор обзора; заметили — охранник и вызов.</p><h2 id="этапы-ночного-взлома-и-налета" tabindex="-1">Этапы ночного взлома и налёта <a class="header-anchor" href="#этапы-ночного-взлома-и-налета" aria-label="Permalink to &quot;Этапы ночного взлома и налёта&quot;">​</a></h2><ol><li><strong>Разведка.</strong> Команда заходит покупателями и смотрит, сколько товара на полках, где камеры, щиток и задняя дверь. Товар завозят по расписанию: после завоза полки полные, после недавнего ограбления — полупустые.</li><li><strong>Подготовка.</strong> Болторез, набор электрика, сумки, маски, машина. Роли делятся заранее: кто на щитке, кто держит зал, кто на полках, кто за рулём.</li><li><strong>Щиток.</strong> Технарь срезает замок щитка болторезом и проходит мини-игру с проводкой. Исходов три. <ul><li>Чисто: сигнализация и камеры молчат 3–5 минут, рольставни поднимаются вручную.</li><li>Частично: тихая тревога уходит с задержкой 60–90 секунд.</li><li>Ошибка: искра, удар током, тревога сразу.</li><li>Без набора электрика тревога срабатывает на первой вскрытой витрине или по кнопке продавца.</li><li>У обесточенного магазина есть цена: тёмную витрину видно с улицы, а электрик-игрок получает заявку на аварию и может приехать в разгар дела.</li></ul></li><li><strong>Вход.</strong> Ночью — задняя дверь отмычкой, и с улицы магазин выглядит нетронутым, или рольставня болторезом. Днём — через парадную в масках.</li><li><strong>Зал.</strong> При налёте силовик держит продавца и посетителей. Шкалу запугивания поднимают прицел, голос в микрофон и выстрел в потолок. Если она падает, продавец жмёт кнопку, а в оружейном тянется за стволом. Посетители — NPC и случайные игроки — становятся свидетелями или заложниками.</li><li><strong>Полки.</strong> Это ядро активности. <ul><li>Каждая секция — контейнер с реальным остатком, тип товара виден заранее.</li><li>Жестов два. «Взять» — по одному предмету, выборочно. «Сгрести» — удержанием, всю секцию: быстрее и шумнее, часть товара бьётся.</li><li>Сумка ограничена объёмом, поэтому игрок выбирает между дорогим мелким и дешёвым крупным. Коробку с телевизором несут к машине в руках.</li><li>Запертую витрину можно разбить (громко, срабатывает датчик), вырезать стеклорезом (тихо, медленно) или открыть ключом продавца, если тот достаточно запуган.</li></ul></li><li><strong>Касса и сейф.</strong> Кассу вскрывают фомкой или заставляют открыть продавца; в ней не больше 15–20% суммы. У сейфа в подсобке замок с задержкой на 2–3 минуты, и команда решает, ждать ли под тревогой. Ключ управляющего открывает сейф сразу, но лежит в другом магазине той же сети.</li><li><strong>Отход.</strong> У побега три ловушки для жадных. <ul><li>Через 40–60 секунд после тревоги опускаются рольставни. Выход остаётся через заднюю дверь или болторезом.</li><li>Кассета с краской метит купюры из кассы, вскрытой без ключа. Меченые деньги придётся отмывать.</li><li>В коробках дорогой техники лежит метка. Полиция видит её сигнал, пока технарь не найдёт метку сканером.</li><li>Каждый следующий магазин за одну вылазку без смены одежды и машины даёт полиции более точное описание.</li></ul></li><li><strong>Сбыт.</strong> Товар уходит покупателям из таблицы типов: электроника — мастерам и скупщикам, детали — оружейникам, украшения — под заказ.</li></ol><p>Люди в цепочке: мастер инструментов, напарники по ролям, посетители, электрик, полиция, скупщик или оружейник.</p><h2 id="если-магазин-принадлежит-игроку" tabindex="-1">Если магазин принадлежит игроку <a class="header-anchor" href="#если-магазин-принадлежит-игроку" aria-label="Permalink to &quot;Если магазин принадлежит игроку&quot;">​</a></h2><p>Владелец теряет ограниченную сумму и получает повод вкладываться в защиту.</p><ul><li>Убыток ограничен и без страховки: с полок пропадает товар не дороже заданной доли недельного оборота, из кассы — не больше дневного лимита.</li><li>Камеры, сейф с задержкой и охранник покупаются; охрану можно нанять из игроков.</li><li>После ограбления полки пусты до завоза, а завоз — это рейс для игрока-водителя.</li><li>У системного магазина владельца нет: он теряет только запас на полках, который восстанавливается завозом по расписанию.</li></ul>',14)])])}const _=d(a,[["render",e]]);export{p as __pageData,_ as default};
